const jar = {
  label: "honey",
  read() {
    return this === undefined ? "none" : this.label;
  },
};

function call(fn) {
  return fn();
}

const { read } = jar;
const shelf = { label: "shelf", read };

console.log(read());
console.log(call(jar.read));
console.log(call(() => jar.read()));
console.log(shelf.read());
